  final int exitCode;
  final String output;
  final Map<String, String> outputs; // GITHUB_OUTPUT key=values
  final List<String> ghLog; // stubbed gh invocations
  final List<String> curlLog; // stubbed curl invocations

  bool get changed => outputs['changed'] == 'true';
