    'FA_REAL_GIT': realGit,
    'FA_RACER': racer,
    'FA_RACE_FILE': raceFile,
    'FA_FLUTTER_FAIL': '${root.path}/flutter-fail',
    'FA_FLUTTER_DIRTY': '${root.path}/flutter-dirty',
