        isFalse,
        reason: 'the resolved git must never be an agent-session guard shim',
      );
      final r = Process.runSync(git, ['--version']);
      expect(r.exitCode, 0, reason: r.stderr.toString());
      expect(r.stdout.toString(), startsWith('git version'));
