      expect(r.exitCode, 0, reason: r.output);
      expect(r.output, contains('DRY-RUN: would push'));
      expect(r.output, contains('v0.1.496'));
      expect(r.output, contains('would then cut annotated tag v0.1.496'));
      expect(
        r.originHeadAfter,
        r.originHeadBefore,
