  File('$seed/flutter_app/pubspec.lock').writeAsStringSync(
    '# Generated by pub (sandbox seed)\n'
    'packages:\n'
    '  flutter_agent_harness:\n'
    '    description:\n'
    '      path: ".."\n'
    '    source: path\n'
    '    version: "0.1.495"\n',
  );
  Directory('$seed/flutter_app/ios').createSync();
  File(
    '$seed/flutter_app/ios/Podfile.lock',
