      expect(r.exitCode, isNot(0), reason: r.output);
      expect(r.output, contains('::error::'));
      expect(r.output, contains('262144'));
      expect(r.output, contains('CHANGELOG_ARCHIVE.md'),
          reason: 'the error must name the fix (archive the tail)');
      expect(
        r.originHeadAfter,
        r.originHeadBefore,
