  git(['commit', '-q', '-m', 'pending work']);
  git(['push', '-q', 'origin', 'main']);
  git(['clone', '-q', origin, racer], cwd: root.path);

  String originMain() {
    final r = Process.runSync(realGit, [
      '--git-dir',
